ReplacementChunks.TargetContent:
body {
  min-height: 100vh;
  background: var(--bg);
  position: relative;
  overflow-x: hidden;
}

body::before {
  content: "";
  position: fixed;
  top: -20%;
  left: -10%;
  width: 50%;
  height: 50%;
  background: radial-gradient(circle, rgba(0, 216, 192, 0.15) 0%, transparent 70%);
  filter: blur(80px);
  animation: cyanGlow 8s ease-in-out infinite alternate;
  z-index: -1;
}

body::after {
  content: "";
  position: fixed;
  bottom: -20%;
  right: -10%;
  width: 50%;
  height: 50%;
  background: radial-gradient(circle, rgba(255, 215, 0, 0.12) 0%, transparent 70%);
  filter: blur(80px);
  animation: goldGlow 10s ease-in-out infinite alternate-reverse;
  z-index: -1;
}

@keyframes cyanGlow {
  0% {
    transform: translate(0, 0) scale(1);
    opacity: 0.8;
  }
  100% {
    transform: translate(50px, 30px) scale(1.2);
    opacity: 1;
  }
}

@keyframes goldGlow {
  0% {
    transform: translate(0, 0) scale(1);
    opacity: 0.7;
  }
  100% {
    transform: translate(-40px, -20px) scale(1.1);
    opacity: 0.9;
  }
}

